insert into public.questions (slug, subject_id, chapter_id, type, prompt_html, explanation_html, points) values ('thales-q1', (select id from public.subjects where code = 'MATH'), (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '3E') and c.slug = 'theoreme-de-thales'), 'single_choice', $html$<p>Dans un triangle ABC, M ∈ [AB], N ∈ [AC] et (MN) // (BC). Quelle égalité est vraie ?</p>$html$, $html$<p>Le théorème de Thalès compare les côtés du petit triangle AMN à ceux du grand triangle ABC, dans le même ordre : <span class="frac"><span>AM</span><span>AB</span></span> = <span class="frac"><span>AN</span><span>AC</span></span> = <span class="frac"><span>MN</span><span>BC</span></span>.</p>$html$, 3);
insert into public.question_options (question_id, slug, label_html, sort_order) values ((select id from public.questions where slug = 'thales-q1'), 'thales-q1-a', $html$<span class="frac"><span>AM</span><span>AB</span></span> = <span class="frac"><span>AN</span><span>AC</span></span> = <span class="frac"><span>MN</span><span>BC</span></span>$html$, 0);
insert into public.question_options (question_id, slug, label_html, sort_order) values ((select id from public.questions where slug = 'thales-q1'), 'thales-q1-b', $html$<span class="frac"><span>AM</span><span>MB</span></span> = <span class="frac"><span>MN</span><span>BC</span></span>$html$, 1);
insert into public.question_options (question_id, slug, label_html, sort_order) values ((select id from public.questions where slug = 'thales-q1'), 'thales-q1-c', $html$<span class="frac"><span>AB</span><span>AM</span></span> = <span class="frac"><span>AC</span><span>NC</span></span>$html$, 2);
insert into public.question_options (question_id, slug, label_html, sort_order) values ((select id from public.questions where slug = 'thales-q1'), 'thales-q1-d', $html$<span class="frac"><span>AM</span><span>AC</span></span> = <span class="frac"><span>AN</span><span>AB</span></span>$html$, 3);
insert into private.answer_keys (question_id, correct_option_ids, accepted_texts, numeric_value, expected_answer) values ((select id from public.questions where slug = 'thales-q1'), array(select o.id from public.question_options o join public.questions qq on qq.id = o.question_id where qq.slug = 'thales-q1' and o.slug = any (array['thales-q1-a']::text[])), array[]::text[], null, null);
insert into public.questions (slug, subject_id, chapter_id, type, prompt_html, explanation_html, points) values ('thales-q2', (select id from public.subjects where code = 'MATH'), (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '3E') and c.slug = 'theoreme-de-thales'), 'numeric', $html$<p>Avec (MN) // (BC), AM = 3 cm, AB = 5 cm et AC = 10 cm. Calcule AN (en cm).</p>$html$, $html$<p><span class="frac"><span>AM</span><span>AB</span></span> = <span class="frac"><span>AN</span><span>AC</span></span> donc AN = <span class="frac"><span>AM × AC</span><span>AB</span></span> = <span class="frac"><span>3 × 10</span><span>5</span></span> = <strong>6 cm</strong>.</p>$html$, 4);
insert into private.answer_keys (question_id, correct_option_ids, accepted_texts, numeric_value, expected_answer) values ((select id from public.questions where slug = 'thales-q2'), array(select o.id from public.question_options o join public.questions qq on qq.id = o.question_id where qq.slug = 'thales-q2' and o.slug = any (array[]::text[])), array[]::text[], 6, '6 cm');
insert into public.questions (slug, subject_id, chapter_id, type, prompt_html, explanation_html, points) values ('thales-q3', (select id from public.subjects where code = 'MATH'), (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '3E') and c.slug = 'theoreme-de-thales'), 'numeric', $html$<p>Dans la même figure, BC = 7,5 cm. Calcule MN (en cm).</p>$html$, $html$<p><span class="frac"><span>MN</span><span>BC</span></span> = <span class="frac"><span>AM</span><span>AB</span></span> donc MN = <span class="frac"><span>7,5 × 3</span><span>5</span></span> = <strong>4,5 cm</strong>.</p>$html$, 4);
insert into private.answer_keys (question_id, correct_option_ids, accepted_texts, numeric_value, expected_answer) values ((select id from public.questions where slug = 'thales-q3'), array(select o.id from public.question_options o join public.questions qq on qq.id = o.question_id where qq.slug = 'thales-q3' and o.slug = any (array[]::text[])), array[]::text[], 4.5, '4,5 cm');
insert into public.questions (slug, subject_id, chapter_id, type, prompt_html, explanation_html, points) values ('thales-q4', (select id from public.subjects where code = 'MATH'), (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '3E') and c.slug = 'theoreme-de-thales'), 'true_false', $html$<p>Si A, M, B et A, N, C sont alignés dans le même ordre et <span class="frac"><span>AM</span><span>AB</span></span> = <span class="frac"><span>AN</span><span>AC</span></span>, alors (MN) // (BC).</p>$html$, $html$<p><strong>Vrai</strong> : c’est la réciproque du théorème de Thalès.</p>$html$, 3);
