insert into public.questions (slug, subject_id, chapter_id, type, prompt_html, explanation_html, points) values ('thales-q5', (select id from public.subjects where code = 'MATH'), (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '3E') and c.slug = 'theoreme-de-thales'), 'multiple_choice', $html$<p>Dans quelles situations peut-on appliquer le théorème de Thalès ? (plusieurs réponses)</p>$html$, $html$<p>Il faut deux droites sécantes et deux droites parallèles : c’est le cas du triangle et du papillon. Le triangle rectangle relève de Pythagore ou de la trigonométrie.</p>$html$, 3);
