insert into public.questions (slug, subject_id, chapter_id, type, prompt_html, explanation_html, points) values ('thales-e1', (select id from public.subjects where code = 'MATH'), (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '3E') and c.slug = 'theoreme-de-thales'), 'numeric', $html$<p>(MN) // (BC), AM = 2, AB = 8 et AN = 3. Calcule AC.</p>$html$, $html$<p>AC = <span class="frac"><span>AN × AB</span><span>AM</span></span> = <span class="frac"><span>3 × 8</span><span>2</span></span> = <strong>12</strong>.</p>$html$, 5);
insert into private.answer_keys (question_id, correct_option_ids, accepted_texts, numeric_value, expected_answer) values ((select id from public.questions where slug = 'thales-e1'), array(select o.id from public.question_options o join public.questions qq on qq.id = o.question_id where qq.slug = 'thales-e1' and o.slug = any (array[]::text[])), array[]::text[], 12, '12');
insert into public.questions (slug, subject_id, chapter_id, type, prompt_html, explanation_html, points) values ('thales-e2', (select id from public.subjects where code = 'MATH'), (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '3E') and c.slug = 'theoreme-de-thales'), 'single_choice', $html$<p>Dans une configuration papillon où (MN) // (BC), le point A est…</p>$html$, $html$<p>Dans le papillon, A est le point où se croisent les droites (BM) et (CN).</p>$html$, 5);
