insert into public.questions (slug, subject_id, chapter_id, type, prompt_html, explanation_html, points) values ('thales-e3', (select id from public.subjects where code = 'MATH'), (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '3E') and c.slug = 'theoreme-de-thales'), 'true_false', $html$<p>Points dans le même ordre, <span class="frac"><span>AM</span><span>AB</span></span> = <span class="frac"><span>4</span><span>6</span></span> et <span class="frac"><span>AN</span><span>AC</span></span> = <span class="frac"><span>6</span><span>9</span></span> : (MN) est parallèle à (BC).</p>$html$, $html$<p><strong>Vrai</strong> : <span class="frac"><span>4</span><span>6</span></span> = <span class="frac"><span>6</span><span>9</span></span> = <span class="frac"><span>2</span><span>3</span></span>, donc d’après la réciproque, (MN) // (BC).</p>$html$, 5);
